    'about.lead':           '我是周骏（JUN），视觉设计师，现居西班牙马德里。过去十余年，我一直在做同一件事：把混乱的信息整理成一套看得懂的视觉系统。\n2013 年从公益组织的宣传物料做起，2016 年进入心理测评行业 —— 网页视觉、系统原型、儿童测评动画；近年专注医学量表的报告版式体系、品牌识别系统与出版设计。206 份量表报告共用一套模板系统，44 页的品牌手册从标志制图到办公物料一页页画完。\n在西班牙之后，我希望把这套「把复杂东西理清楚」的能力，用在更跨文化的场景里。同时持续关注最新前沿设计趋势，掌握 AI 技能，让 AI 赋能设计全流程。',
