    'pc19.ov.p1'            : '这是为**平原商场**打造的 2019 年度台历，主题为**「时光旅历」**。扉页以「出彩的足迹」时间轴回顾商场 1957—2018 年的发展历程，再以「贰零壹玖用心体会，只做咱老百姓的商场」开启新一年。',
    'pc19.ov.p2'            : '每月一幅**品牌主题插画**，将商场各楼层与入驻品牌（羽绒服、美妆、男装、女鞋、儿童娱乐城、内衣、名表、黄金珠宝等）融入苹果吉祥物「平平」的生活场景；配套日历页标注公历、农历、节气与节日，底部绘制品牌街景，让台历既是时间工具，也是商场全年的品牌画卷。',
    'pc19.ov.point1'        : '苹果吉祥物「平平」贯穿 12 个月',
    'pc19.ov.point2'        : '扉页含商场 60 年历史时间轴',
