    'pc19.ft1.t'            : '扉页讲述商场 60 年',
    'pc19.ft1.p'            : '封面以猪年喜庆氛围开场，「出彩的足迹」时间轴串联 1957 年开业至 2018 年蝶变升级的十个关键节点，再由「时光旅历」标题页承上启下，把品牌历史写进新年。',
    'pc19.ft2.no'           : '02 — 苹果吉祥物「平平」',
    'pc19.ft2.t'            : '平平逛遍整座商场',
    'pc19.ft2.p'            : '拟人化的苹果形象「平平」是全年主角，它试羽绒服、买美妆、逛男装、挑女鞋、带娃去娱乐城、选黄金珠宝……以顾客视角把商场各楼层串成一条温暖的生活动线。',
