    'pc21.ov.p1'            : '这是为**平原商场**打造的 2021 年度台历。封面以辛丑牛年喜庆氛围开场，金色大牛与苹果吉祥物「平平」家族同框，红色囍字建筑、烟花灯笼、铜钱烘托新年气氛。',
    'pc21.ov.p2'            : '扉页创新设置**「平原商场报」**报纸风格页与**「平原邮政」**明信片页，前者以头条新闻形式传递品牌理念，后者以邮票和邮戳增添收藏趣味。每月一幅**楼层主题插画**，平平带着家人朋友逛遍商场各楼层——从周大福珠宝到 2F 女鞋箱包，从 3F 运动休闲到 6 楼儿童卖场，从建店 64 周年庆典到新大楼开业 21 周年，把商场的业态地图和品牌故事画进了一整年。',
    'pc21.ov.point1'        : '苹果吉祥物「平平」贯穿全年',
