    'pc22.ov.mascot.v'      : '平平（苹果延伸形象）',
    'pc22.ov.p1'            : '这是为**平原商场**打造的 2022 年度台历。封面以壬寅虎年喜庆氛围开场，金色大老虎（额头王字）与苹果吉祥物「平平」家族穿古装同框——嫦娥弹琵琶、虎帽舞狮者——橙红色放射背景、祥云山峦烘托新年气势。',
    'pc22.ov.p2'            : '扉页创新设置**「平原商场抵用券」**双页，共 30 张优惠券覆盖 1F 至 9F 各楼层品牌，兼具实用与收藏价值。每月一幅**楼层主题插画**，平平带着家人朋友逛遍商场各楼层——从珠宝城求婚到 SHOES 鞋包店，从三楼运动馆到四楼女装扮靓新乡，从建店 65 周年庆典到新大楼开业 22 周年，把商场的业态地图和品牌故事画进了一整年。',
    'pc22.ov.point1'        : '苹果吉祥物「平平」贯穿全年',
