    'pc23.ov.mascot.v'      : '平平（苹果延伸形象）',
    'pc23.ov.p1'            : '这是为**平原商场**打造的 2023 年度台历。封面以癸卯兔年喜庆氛围开场，白兔戴花冠骑鹿，苹果吉祥物「平平」化作飞天造型——吹笛、弹琵琶、翩翩起舞——天灯、锦鲤、祥云环绕，粉色背景温柔浪漫。',
    'pc23.ov.p2'            : '扉页创新设置**「平平书签」**双页，共 8 枚可剪下的书签：平安、大吉、如意、事成与兔年大吉系列，传统屋檐灯笼配舞狮帽平平，「伴您阅读每一天」。每月一幅**楼层主题插画**，平平带着家人朋友逛遍商场各楼层——从黄金珠宝广场七大品牌到二楼鞋履舞龙，从三楼男装咖啡馆到四楼品质女装，从建店 66 周年施工庆典到新大楼开业 23 周年，把商场的业态地图和品牌故事画进了一整年。',
    'pc23.ov.point1'        : '苹果吉祥物「平平」贯穿全年',
    'pc23.ov.point2'        : '平平书签双扉页 · 8 枚可剪下',
    'pc23.ov.point3'        : '每月对应一个商场楼层/业态',
