    'about.eyebrow':        'Sobre mí',
    'about.title':          'Terminar bien el trabajo cuesta más que hacerlo bonito',
    'about.lead':           'Soy Jun Zhou (JUN), diseñador visual, residente en Madrid. Durante más de diez años he hecho lo mismo: convertir información desordenada en un sistema visual comprensible.\nEmpecé en 2013 con materiales de comunicación para una organización de voluntariado; en 2016 entré en el sector de la evaluación psicológica —diseño web, prototipos de sistema, animación para evaluación infantil—. En los últimos años me he centrado en el sistema de maquetación de informes de escalas clínicas, los sistemas de identidad de marca y el diseño editorial. 206 informes comparten una misma plantilla; un manual de marca de 44 páginas está dibujado página a página, de la construcción del logotipo a la papelería.\nYa en España, quiero aplicar esta capacidad de ordenar lo complejo a contextos más interculturales. Al mismo tiempo, sigo de cerca las últimas tendencias del diseño y domino la IA para potenciar todo el flujo de diseño.',
    'about.principle.title':'Principios',
    'about.principle.1':    'Sistema antes que pieza: un informe bonito es fácil, doscientos igual de buenos es diseño',
    'about.principle.2':    'La información manda: el ornamento se subordina a la legibilidad, sobre todo en contenido clínico',
    'about.principle.3':    'Cuidar el detalle: puntuación, interlineado, blancos y línea de corte son el suelo de lo profesional',
    'about.principle.4':    'Diseñar para producir: cada decisión visual debe imprimirse, fabricarse y poder reutilizarse',

    'about.timeline.eyebrow':'Trayectoria',
    'about.timeline.title': 'De materiales benéficos a sistemas de informes clínicos',

    'about.timeline.1.year':'2019 — Actualidad',
    'about.timeline.1.t':   'Diseñador visual · Ruizhi Cloud',
    'about.timeline.1.d':   'Ruizhi Cloud Intelligent Technology (Guangdong) · plataforma de evaluación psicológica e infantil. Responsable del sistema de maquetación de informes (más de 200 plantillas), del sistema de identidad de marca (manual VI de 44 páginas), de manuales y catálogos, del sistema de certificados y de packaging.',
    'about.timeline.2.year':'06.2016 — Actualidad',
    'about.timeline.2.t':   'Diseñador visual · Instituto de Medición Psicológica / Haiyang Education',
    'about.timeline.2.d':   'Al servicio del Instituto de Medición Psicológica de Shenzhen y de Haiyang Education (Zhuhai). VIS corporativo, diseño web, estructuración y prototipado de los sistemas de evaluación ASQ y M-CHAT, y diseño de storyboards y animación del módulo de medición.',
    'about.timeline.3.year':'09.2013 — 06.2016',
    'about.timeline.3.t':   'Diseñador gráfico · Federación de Voluntarios',
    'about.timeline.3.d':   'Centro de Servicio Voluntario Honglingjin. Materiales completos de campañas benéficas (carteles, paneles, roll-ups, folletos, huchas), gestión visual de redes sociales, mascota y stickers para WeChat. El proyecto principal obtuvo el premio del Concurso Nacional de Proyectos de Voluntariado Juvenil 2015 y dio lugar a la IP «Shiliu Mei».',

    'about.advantages.title':'Puntos fuertes',

    'about.advantages.lead': 'Más de diez años convirtiendo lo visual en sistema',
    'about.advantages.l1':  'Convierto un conjunto visual en sistema: 206 informes con una sola plantilla, 44 páginas de manual normalizadas una a una',
    'about.advantages.l2':  'Base sólida en diseño de información: años trabajando con escalas clínicas y datos de evaluación',
    'about.advantages.l3':  'Marca, editorial, interfaz, IP, packaging y espacio: seis áreas que funcionan solas o combinadas',
    'about.advantages.l4':  'Dominio de artes gráficas, junto con capacidad de interfaz y motion: el estático y el dinámico no se separan',
    'about.advantages.l5':  'Chino nativo, inglés profesional, español en aprendizaje. Zona horaria CET, trabajo remoto fluido',

