    'pc.ov.extra.v'       : 'Términos solares · Cupones de marca',
    'pc.ov.p1'            : 'Es el calendario anual 2018 creado para **Pingyuan Mall**. Su hilo conductor es una manzana roja antropomórfica, **«Pingping»**, mascota de marca que protagoniza la cubierta y se transforma en el «0» de «2018»: el recurso más reconocible de todo el proyecto.',
    'pc.ov.p2'            : 'Cada mes combina una **página ilustrada** (danza del león, San Valentín, plantación de árboles, mercado bajo la lluvia, estanque de lotos, cosecha…) con una **página de calendario funcional** (calendario gregoriano y lunar, términos solares, festividades y cupones de las marcas del centro). Narrativa y utilidad se alternan: sirve para consultar la fecha y también como compañía de marca durante todo el año.',
    'pc.ov.point1'        : '«Pingping» recorre los 12 meses como sello unificador',
    'pc.ov.point2'        : 'Meses bilingües y columna de marca vertical',
    'pc.ov.point3'        : 'Festejo chino en rojo y oro + hitos internacionales',
    'pc.ov.point4'        : 'Cupones de marca integrados en las páginas de calendario',
    'pc.ft1.no'           : '01 — Mascota de marca',
    'pc.ft1.t'            : 'La manzana «Pingping» sustituye al 0',
    'pc.ft1.p'            : 'La manzana roja «Pingping» protagoniza la cubierta y a la vez se convierte en el «0» de 2018. De la página de plan anual al resumen de cierre, la misma figura reaparece hasta fijarse como recuerdo de marca.',
    'pc.ft2.no'           : '02 — Ilustración narrativa',
    'pc.ft2.t'            : '12 meses, 12 escenas',
    'pc.ft2.p'            : 'Una ilustración original por mes: la danza del león en enero, la playa en junio, la tienda de barrio en agosto, la casa de Papá Noel en diciembre… Un relato del año construido sobre términos solares y festividades, cálido y cotidiano.',
    'pc.ft3.no'           : '03 — Página funcional',
    'pc.ft3.t'            : 'Calendario y cupones en una página',
    'pc.ft3.p'            : 'La página de calendario anota fechas gregorianas y lunares, términos solares y fiestas tradicionales, e integra a la derecha los cupones de las marcas del centro: el uso diario se convierte en un canal de tráfico a la tienda.',
    'pc.ft4.no'           : '04 — Sistema visual',
    'pc.ft4.t'            : 'Rojo y oro × guiños internacionales',
    'pc.ft4.p'            : 'Farolillos, el carácter de la fortuna y carpas conviven con la Estatua de la Libertad y la Torre Eiffel; la columna vertical «Pingyuan» y los meses bilingües recorren todo el volumen. Festivo sin perder la mirada internacional.',
    'pc.mk1.cap'          : 'Doble página abierta · Ilustración y calendario',
