    'pc19.ov.extra.v'       : 'Viaje en el tiempo · El centro del pueblo',
    'pc19.ov.p1'            : 'Es el calendario anual 2019 creado para **Pingyuan Mall**. Su tema es **«Viaje en el tiempo»**: una página de apertura con la línea de tiempo «Huellas brillantes» repasa la historia del centro de 1957 a 2018, y el lema «2019 con atención, el centro del pueblo» abre el nuevo año.',
    'pc19.ov.p2'            : 'Cada mes una **ilustración temática de marca** integra las plantas y marcas del centro (abrigos, maquillaje, ropa de hombre, zapatos, zona infantil, ropa interior, relojes, oro y joyas…) en la vida cotidiana de la manzana «Pingping». La página de calendario anota fechas gregorianas y lunares, términos solares y festividades, y dibuja la calle de marcas al pie: un cuadro de marca de todo el año.',
    'pc19.ov.point1'        : 'La manzana «Pingping» recorre los 12 meses',
