    'pc19.ov.point4'        : 'Calle de marcas al pie del calendario',
    'pc19.ft1.no'           : '01 — Tema: Viaje en el tiempo',
    'pc19.ft1.t'            : 'La apertura cuenta 60 años',
    'pc19.ft1.p'            : 'La cubierta abre con el ambiente festivo del Año del Cerdo; la línea de tiempo «Huellas brillantes» enlaza diez hitos del centro desde su apertura en 1957 hasta su transformación en 2018, y la página título «Viaje en el tiempo» sirve de puente para escribir la historia de marca en el nuevo año.',
    'pc19.ft2.no'           : '02 — Mascota: manzana «Pingping»',
    'pc19.ft2.t'            : 'Una manzana «Pingping» recorre el centro',
    'pc19.ft2.p'            : 'La manzana «Pingping» antropomórfica es la protagonista del año: prueba abrigos, compra maquillaje, recorre la ropa de hombre, elige zapatos, lleva a los niños a la zona infantil y escoge oro y joyas… Desde la mirada del cliente, enlaza las plantas del centro en una cálida línea de vida.',
    'pc19.ft3.no'           : '03 — Ilustración de marca',
    'pc19.ft3.t'            : '12 meses, 12 escenas de marca',
    'pc19.ft3.p'            : 'Cada mes una ilustración original corresponde a una marca o planta: Qiangren, Playboy, Manka Road, Miao Ren, Jiuluwang, Laomiao Gold, Lao Feng Xiang… El slogan de marca al pie de cada ilustración funde la información comercial en la narrativa.',
    'pc19.ft4.no'           : '04 — Página funcional',
    'pc19.ft4.t'            : 'Términos solares + calle de marcas',
    'pc19.ft4.p'            : 'La página de calendario anota fechas gregorianas y lunares, términos solares y festividades tradicionales, y dibuja la calle de la marca del mes al pie, haciendo eco de la ilustración: pasar las páginas se vuelve un paseo por los escaparates del centro.',
    'pc19.mk1.cap'          : 'Doble página abierta · Ilustración y calendario',
