    'pc20.ov.mascot.v'      : 'Pingping (de una manzana)',
    'pc20.ov.p1'            : 'Es el calendario anual 2020 creado para **Pingyuan Mall**. La cubierta abre con el ambiente festivo del Año de la Rata: la manzana «Pingping» comparte escena con ratones, y un edificio con el carácter 囍, fuegos artificiales y faroles realzan el aire de Año Nuevo.',
    'pc20.ov.p2'            : 'Las páginas de apertura presentan **«Honours 荣誉历程»** y **«Culture 企业文化»**, dos páginas de marca que muestran los galardones del centro y su filosofía. Cada mes, una **ilustración temática de planta**: Pingping recorre el centro con familia y amigos —del 1º piso de relojes y cosmética al 7º de abrigos, de las rebajas infantiles a la limpieza de electrodomésticos— dibujando el mapa comercial del centro a lo largo de todo el año.',
    'pc20.ov.point1'        : 'La manzana «Pingping» recorre el año',
    'pc20.ov.point2'        : 'Dos aperturas: honores y cultura',
    'pc20.ov.point3'        : 'Cada mes, una planta o negocio',
    'pc20.ov.point4'        : 'Octubre: 20º aniversario del centro',
    'pc20.ft1.no'           : '01 — Cubierta Año de la Rata',
    'pc20.ft1.t'            : 'Mascota: manzana «Pingping»',
    'pc20.ft1.p'            : '«Pingping» es un personaje nacido de una manzana: cuerpo rosado y redondo, antenas de pedúnculo amarillo y cola de hoja verde, con altísima reconocibilidad. En la cubierta de 2020 comparte escena con ratones, llena de alegría y fiesta.',
    'pc20.ft2.no'           : '02 — Dos aperturas de marca',
    'pc20.ft2.t'            : 'Honours + Culture',
    'pc20.ft2.p'            : 'El calendario abre con dos páginas de marca: «Honours» muestra en una línea de tiempo los galardones del centro a lo largo de los años, y «Culture» transmite su filosofía de gestión, dando al calendario también función de manual de marca.',
    'pc20.ft3.no'           : '03 — Ilustración de planta',
    'pc20.ft3.t'            : '12 meses por todo el centro',
    'pc20.ft3.p'            : 'Cada mes la ilustración corresponde a una planta o negocio: relojes y cosmética en 1F, zapatos y bolsos en 2F, ropa de hombre en 3F, ropa infantil y femenina en 4F, ropa interior femenina en 5F, rebajas infantiles en 6F, abrigos en 7F, más deportes, electrodomésticos, joyería y la fiesta del 20º aniversario.',
    'pc20.ft4.no'           : '04 — Página funcional',
    'pc20.ft4.t'            : 'Términos solares + marca',
    'pc20.ft4.p'            : 'La página de calendario anota fechas gregorianas y lunares, términos solares y festividades tradicionales, e imprime al pie el lema de marca «Pingyuan, el centro del pueblo», transmitiendo el calor de la marca a cada paso.',
