    'pc21.ov.mascot.k'      : 'Mascota',
    'pc21.ov.mascot.v'      : 'Pingping (de una manzana)',
    'pc21.ov.p1'            : 'Es el calendario anual 2021 creado para **Pingyuan Mall**. La cubierta abre con el ambiente festivo del Año del Buey: un gran buey dorado comparte escena con la familia de la manzana «Pingping», y un edificio con el carácter 囍, fuegos artificiales, faroles y monedas de bronce realzan el aire de Año Nuevo.',
    'pc21.ov.p2'            : 'Las páginas de apertura innovan con **«Pingyuan Mall News»**, una página estilo periódico, y **«Pingyuan Post»**, una postal: la primera transmite la filosofía de marca en forma de titular, la segunda añade sellos y matasellos para coleccionar. Cada mes, una **ilustración temática de planta**: Pingping recorre el centro con familia y amigos —de las joyas Chow Tai Fook a zapatos y bolsos en 2F, del deporte en 3F a la zona infantil en 6F, del 64º aniversario de la tienda a los 21 años del nuevo edificio— dibujando el mapa comercial y la historia de marca del centro a lo largo de todo el año.',
    'pc21.ov.point1'        : 'La manzana «Pingping» recorre el año',
    'pc21.ov.point2'        : 'Periódico + postal especiales',
    'pc21.ov.point3'        : 'Cada mes, una planta o negocio',
    'pc21.ov.point4'        : 'Julio: 64º aniversario · Oct: 21º del edificio',
    'pc21.ft1.no'           : '01 — Cubierta Año del Buey',
    'pc21.ft1.t'            : 'Mascota: manzana «Pingping»',
    'pc21.ft1.p'            : '«Pingping» es un personaje nacido de una manzana: cuerpo rosado y redondo, antenas de pedúnculo amarillo y cola de hoja verde, con altísima reconocibilidad. En la cubierta de 2021 la familia Pingping comparte escena con un gran buey dorado, llena de alegría y fiesta.',
    'pc21.ft2.no'           : '02 — Dos aperturas especiales',
    'pc21.ft2.t'            : 'Periódico + Postal',
    'pc21.ft2.p'            : 'El calendario abre con dos páginas creativas: «Pingyuan Mall News» transmite la filosofía de marca «El centro del pueblo» en forma de titular de periódico; la postal «Pingyuan Post» incluye sellos y matasellos, sumando coleccionismo e interactividad.',
    'pc21.ft3.no'           : '03 — Ilustración de planta',
    'pc21.ft3.t'            : '12 meses por todo el centro',
    'pc21.ft3.p'            : 'Cada mes la ilustración corresponde a una planta o negocio: joyas Chow Tai Fook, zapatos y bolsos en 2F, deporte en 3F, ropa femenina de lujo en 4F, zona infantil en 6F, abrigos en 7F, ropa interior en 5F, más el 64º aniversario de la tienda, el cuidado al empleado y los 21 años del nuevo edificio.',
    'pc21.ft4.no'           : '04 — Página funcional',
    'pc21.ft4.t'            : 'Ilustración + calendario + términos',
    'pc21.ft4.p'            : 'En 2021 la página de calendario adopta un nuevo diseño: ilustración del personaje a la izquierda y cuadrícula del calendario a la derecha, anota fechas gregorianas y lunares, términos solares y festividades, e imprime al pie el lema «Pingyuan, el centro del pueblo», transmitiendo el calor de la marca a cada paso.',
    'pc21.mk1.cap'          : 'Doble página abierta · Ilustración y calendario',
