    'pc22.meta.desc'        : 'Calendario anual 2022 del centro comercial Pingyuan: la manzana «Pingping» como mascota de marca, doble página de cupones, 12 ilustraciones temáticas por plantas y 12 páginas de calendario funcional. Diseño gráfico de JUN (Zhou Jun).',
