    'pc22.hero.sub'         : 'Calendario anual 2022 · Año del Tigre',
    'pc22.hero.desc'        : 'Un calendario anual protagonizado por la manzana «Pingping»: portada del Año del Tigre con un gran tigre dorado junto a Pingping de época, doble página de cupones con treinta descuentos del 1F al 9F y 12 ilustraciones temáticas por plantas — acompaña a Pingping por cada piso del centro.',
