    'pc22.ov.mascot.k'      : 'Mascota',
    'pc22.ov.mascot.v'      : 'Pingping (de una manzana)',
    'pc22.ov.p1'            : 'Es el calendario anual 2022 creado para **Pingyuan Mall**. La cubierta abre con el ambiente festivo del Año del Tigre: un gran tigre dorado con el carácter 王 en la frente comparte escena con la familia de la manzana «Pingping» vestida de época — una Chang\'e con pipa y un danzante de león con gorro de tigre — sobre un fondo radial naranja rojizo con nubes auspiciosas y montañas.',
    'pc22.ov.p2'            : 'Las páginas de apertura innovan con la **doble página de «Cupones Pingyuan»**: treinta cupones cubren las marcas del 1F al 9F, prácticas y coleccionables. Cada mes, una **ilustración temática de planta**: Pingping recorre el centro con familia y amigos —de la propuesta en la joyería a la zapatería SHOES, del pabellón deportivo del 3º a la moda femenina del 4º, del 65º aniversario de la fundación a los 22 años del nuevo edificio— dibujando el mapa comercial y la historia de marca del centro a lo largo de todo el año.',
    'pc22.ov.point1'        : 'La manzana «Pingping» recorre el año',
    'pc22.ov.point2'        : 'Doble página de cupones · 30 descuentos',
    'pc22.ov.point3'        : 'Cada mes, una planta o negocio',
    'pc22.ov.point4'        : 'Julio: 65º aniversario · Octubre: 22 años del nuevo edificio',
    'pc22.ft1.no'           : '01 — Cubierta Año del Tigre',
    'pc22.ft1.t'            : 'Gran tigre dorado × Pingping de época',
    'pc22.ft1.p'            : '«Pingping» es un personaje nacido de una manzana: cuerpo rosado y redondo, antenas de pedúnculo amarillo y cola de hoja verde. En la cubierta de 2022 la familia Pingping viste de época — Chang\'e con pipa, danza del león con gorro de tigre — junto al gran tigre dorado, sobre un fondo radial naranja rojizo de gran fuerza.',
    'pc22.ft2.no'           : '02 — Doble página de cupones',
    'pc22.ft2.t'            : '30 cupones del 1F al 9F',
    'pc22.ft2.p'            : 'El calendario abre con dos páginas de cupones: treinta cupones de marca, desde la joyería del 1F y la ropa deportiva del 3F hasta la restauración y ocio del 9F; cada planta tiene su beneficio, y hojear el calendario es también una guía de compras del centro.',
    'pc22.ft3.no'           : '03 — Ilustración de planta',
    'pc22.ft3.t'            : '12 meses por todo el centro',
    'pc22.ft3.p'            : 'Cada mes la ilustración corresponde a una planta o negocio: propuesta en la joyería, zapatería SHOES, pabellón deportivo del 3º, moda femenina del 4º, Día del Niño, abrigos de rebajas en el 7º, electrodomésticos Bafang, moda popular del 5º, más el 65º aniversario y los 22 años del nuevo edificio.',
    'pc22.ft4.no'           : '04 — Página funcional',
    'pc22.ft4.t'            : 'Calendario a la izquierda, ilustración a la derecha',
    'pc22.ft4.p'            : 'La página de 2022 combina la rejilla del calendario a la izquierda con la ilustración de la mascota a la derecha, anota fechas gregorianas y lunares, términos solares y festividades, y al pie imprime lemas de marca como «Pingyuan felicita a la ciudadanía por el Año Nuevo», transmitiendo el calor de la marca a cada paso.',
    'pc22.mk1.cap'          : 'Doble página abierta · Ilustración y calendario',
