    'pc23.ov.mascot.k'      : 'Mascota',
    'pc23.ov.mascot.v'      : 'Pingping (de una manzana)',
    'pc23.ov.p1'            : 'Es el calendario anual 2023 creado para **Pingyuan Mall**. La cubierta abre con el ambiente festivo del Año del Conejo: un conejo blanco con corona floral a lomos de un ciervo, y la manzana «Pingping» convertida en apsara — tocando la flauta, la pipa, danzando — rodeada de faroles flotantes, carpas y nubes auspiciosas sobre un fondo rosa tierno y romántico.',
    'pc23.ov.p2'            : 'Las páginas de apertura innovan con la **doble página de «Marcapáginas Pingping»**: ocho marcapáginas recortables — Paz, Gran Fortuna, Deseos cumplidos y serie de Año Nuevo del Conejo — con faroles de alero tradicional y Pingping de danzante, «acompañándote cada día». Cada mes, una **ilustración temática de planta**: Pingping recorre el centro —de la plaza de joyería con siete marcas a la zapatería con danza del dragón del 2º, del bizcocho de moda masculina del 3º a la moda de calidad del 4º, del 66º aniversario de la fundación a los 23 años del nuevo edificio— dibujando el mapa comercial y la historia de marca del centro a lo largo de todo el año.',
    'pc23.ov.point1'        : 'La manzana «Pingping» recorre el año',
    'pc23.ov.point2'        : 'Doble página de marcapáginas · 8 recortables',
    'pc23.ov.point3'        : 'Cada mes, una planta o negocio',
    'pc23.ov.point4'        : 'Julio: 66º aniversario · Octubre: 23 años del nuevo edificio',
    'pc23.ft1.no'           : '01 — Cubierta Año del Conejo',
    'pc23.ft1.t'            : 'Conejo a lomos de ciervo × Pingping apsara',
    'pc23.ft1.p'            : '«Pingping» es un personaje nacido de una manzana: cuerpo rosado y redondo, antenas de pedúnculo amarillo y cola de hoja verde. En la cubierta de 2023 Pingping se convierte en apsara que toca flauta y pipa, junto al conejo blanco con corona floral a lomos de un ciervo, rodeado de faroles flotantes, carpas y nubes: fondo rosa tierno y romántico.',
    'pc23.ft2.no'           : '02 — Doble página de marcapáginas',
    'pc23.ft2.t'            : '8 marcapáginas recortables',
    'pc23.ft2.p'            : 'El calendario abre con dos páginas de marcapáginas: ocho recortables por la línea punteada — Paz, Gran Fortuna, Deseos cumplidos y serie del Año del Conejo — con faroles de alero y Pingping de danzante: «acompañándote cada día, sé mi amigo», prácticos y coleccionables.',
    'pc23.ft3.no'           : '03 — Ilustración de planta',
    'pc23.ft3.t'            : '12 meses por todo el centro',
    'pc23.ft3.p'            : 'Cada mes la ilustración corresponde a una planta o negocio: plaza de joyería con siete marcas, zapatería con danza del dragón en el 2º, café de moda masculina en el 3º, moda de calidad en el 4º, tiovivo del Día del Niño, abrigos en el 7º, electrodomésticos Bafang, moda del 5º, más el 66º aniversario y los 23 años del nuevo edificio.',
    'pc23.ft4.no'           : '04 — Página funcional',
    'pc23.ft4.t'            : 'Calendario a la izquierda, ilustración a la derecha',
    'pc23.ft4.p'            : 'La página de 2023 combina la rejilla del calendario a la izquierda con la ilustración de la mascota a la derecha, anota fechas gregorianas y lunares, términos solares y festividades, y al pie imprime lemas como «Pingyuan felicita a la ciudadanía: próspero Año del Conejo», transmitiendo el calor de la marca a cada paso.',
    'pc23.mk1.cap'          : 'Doble página abierta · Ilustración y calendario',
