    'about.eyebrow':        'About',
    'about.title':          'Finishing the work is harder than making it pretty',
    'about.lead':           'I’m Jun Zhou (JUN), a visual designer based in Madrid. For over a decade I’ve been doing the same thing: turning messy information into a visual system people can actually read.\nI started in 2013 with campaign material for a volunteer organisation; in 2016 I moved into psychological assessment — web visuals, system prototypes, animation for children’s assessments. In recent years I’ve focused on report layout systems for clinical scales, brand identity systems and editorial design. 206 assessment reports share one template; a 44-page brand manual is drawn page by page, from logo construction to stationery.\nNow in Spain, I want to bring this ability to make complex things legible into more cross-cultural contexts. At the same time, I keep up with the latest design trends and master AI skills, letting AI empower the full design workflow.',
    'about.principle.title':'Principles',
    'about.principle.1':    'System before piece — one good report is easy; two hundred equally good ones is design',
    'about.principle.2':    'Information first — decoration serves legibility, especially in clinical content',
    'about.principle.3':    'Sweat the details — punctuation, leading, whitespace and crop marks are the floor of professionalism',
    'about.principle.4':    'Design for production — every visual decision must print, ship and be reusable',

    'about.timeline.eyebrow':'Timeline',
    'about.timeline.title': 'From charity leaflets to clinical report systems',

    'about.timeline.1.year':'2019 — Present',
    'about.timeline.1.t':   'Visual designer · Ruizhi Cloud',
    'about.timeline.1.d':   'Ruizhi Cloud Intelligent Technology (Guangdong) · psychological and child health assessment platform. Responsible for the report layout system (200+ templates), the brand identity system (44-page VI manual), product manuals and brochures, the certificate system, packaging and merchandise.',
    'about.timeline.2.year':'06.2016 — Present',
    'about.timeline.2.t':   'Visual designer · Shenzhen Institute of Psychological Measurement / Haiyang Education',
    'about.timeline.2.d':   'Serving the Shenzhen Institute of Psychological Measurement Technology and Zhuhai Haiyang Education. Corporate VIS, web visuals, structuring and prototyping of the ASQ and M-CHAT assessment systems, and storyboards plus animation for the measurement module.',
