    'pc.ov.extra.k'       : 'Features',
    'pc.ov.extra.v'       : 'Solar terms · Brand coupons',
    'pc.ov.p1'            : 'This is the 2018 annual calendar made for **Pingyuan Mall**. Its through-line is an anthropomorphic red apple, **"Pingping"**, the brand mascot who stars on the cover and turns into the "0" of "2018" — the single most memorable device in the set.',
    'pc.ov.p2'            : 'Every month pairs a **themed illustration page** (lion dance, Valentine\'s Day, tree planting, a rainy market, the lotus pond, the harvest…) with a **functional calendar page** (solar and lunar dates, solar terms, festivals and the mall brands\' coupons). Story and utility alternate, so the calendar works both as a date reference and as a year-long brand companion.',
    'pc.ov.point1'        : '"Pingping" runs through all 12 months as a unifying mark',
    'pc.ov.point2'        : 'Bilingual month labels and a vertical brand column',
    'pc.ov.point3'        : 'Chinese red-and-gold festivity + international landmarks',
    'pc.ov.point4'        : 'Mall brand coupons embedded in the calendar pages',
    'pc.ft1.no'           : '01 — Brand mascot',
    'pc.ft1.t'            : 'The "Pingping" apple replaces the 0',
    'pc.ft1.p'            : 'The red cartoon apple stars on the cover and doubles as the "0" in 2018. From the yearly planner to the year-end summary the same figure returns, until it sticks as a brand memory.',
    'pc.ft2.no'           : '02 — Monthly narrative',
    'pc.ft2.t'            : '12 months, 12 scenes',
    'pc.ft2.p'            : 'One original illustration per month — the lion dance in January, the beach in June, the corner shop in August, Santa\'s cabin in December. A story of the year told through solar terms and festivals: warm and everyday.',
    'pc.ft3.no'           : '03 — Functional page',
    'pc.ft3.t'            : 'Calendar + coupons in one page',
    'pc.ft3.p'            : 'Each calendar page marks solar and lunar dates, solar terms and traditional festivals, and carries the mall brands\' coupons on the right — turning daily use into foot traffic.',
    'pc.ft4.no'           : '04 — Visual system',
    'pc.ft4.t'            : 'Red and gold × international references',
    'pc.ft4.p'            : 'Chinese lanterns, fortune characters and koi share the page with the Statue of Liberty and the Eiffel Tower; a vertical "Pingyuan" column and bilingual month names run through the book. Festive, yet internationally minded.',
    'pc.mk1.cap'          : 'Spread · illustration and calendar page',
    'pc.mk2.cap'          : 'Standing on a desk · Cover key visual',
