    'pc19.meta.desc'        : 'The 2019 annual calendar for Pingyuan Mall: the apple mascot "Pingping", 12 brand-themed illustrations and 12 functional calendar pages, each month paired with a mall floor and its stores. Graphic design by JUN (Zhou Jun).',
