    'pc19.ov.extra.k'       : 'Theme',
    'pc19.ov.extra.v'       : 'Time journey · The people\'s mall',
    'pc19.ov.p1'            : 'This is the 2019 annual calendar made for **Pingyuan Mall**, themed **"Time Journey"**. An opening page with the "Brilliant Footprints" timeline reviews the mall\'s history from 1957 to 2018, then the line "2019 with care — the people\'s mall" opens the new year.',
    'pc19.ov.p2'            : 'Each month a **brand-themed illustration** folds the mall\'s floors and stores (down jackets, makeup, menswear, shoes, kids\' zone, lingerie, watches, gold and jewellery…) into the apple mascot Pingping\'s everyday scene; the paired calendar page marks solar and lunar dates, solar terms and festivals, and draws a brand street at the bottom — making the calendar both a date tool and a year-long brand canvas.',
    'pc19.ov.point1'        : 'The apple mascot runs through all 12 months',
    'pc19.ov.point2'        : 'Opening holds a 60-year history timeline',
    'pc19.ov.point3'        : 'Each month a mall brand or floor theme',
    'pc19.ov.point4'        : 'Brand street drawn at the calendar foot',
    'pc19.ft1.no'           : '01 — Theme: Time journey',
    'pc19.ft1.t'            : 'Opening tells 60 years',
    'pc19.ft1.p'            : 'The cover opens in festive Year-of-the-Pig mood; the "Brilliant Footprints" timeline links ten milestones from the 1957 opening to the 2018 upgrade, and the "Time Journey" title page bridges them, writing the brand\'s history into the new year.',
    'pc19.ft2.no'           : '02 — Mascot: apple',
    'pc19.ft2.t'            : 'The apple mascot roams the whole mall',
    'pc19.ft2.p'            : 'The anthropomorphic apple mascot is the year\'s lead — trying on down jackets, buying makeup, browsing menswear, picking shoes, taking the kids to the play zone, choosing gold and jewellery… seen through the customer\'s eyes, it strings the mall\'s floors into one warm daily thread.',
    'pc19.ft3.no'           : '03 — Monthly brand illustration',
    'pc19.ft3.t'            : '12 months, 12 brand scenes',
    'pc19.ft3.p'            : 'Each month an original illustration matches a store or floor: Qiangren, Playboy, Manka Road, Cat Man, Jiuluwang, Laomiao Gold, Lao Feng Xiang… a brand slogan at the foot of each illustration blends the commercial message into the story.',
    'pc19.ft4.no'           : '04 — Functional calendar page',
    'pc19.ft4.t'            : 'Solar terms + brand street',
    'pc19.ft4.p'            : 'The calendar page marks solar and lunar dates, solar terms and traditional festivals, and draws the month\'s brand street at the foot, echoing the illustration — turning daily page-turning into a stroll past the mall\'s windows.',
    'pc19.mk1.cap'          : 'Spread · illustration and calendar page',
    'pc19.mk2.cap'          : 'Standing on a desk · Cover key visual',
