    'pc20.ov.p1'            : 'This is the 2020 annual calendar made for **Pingyuan Mall**. The cover opens in festive Year-of-the-Rat mood — the apple mascot Pingping shares the frame with mice, while a 囍-character building, fireworks and lanterns set the New Year tone.',
    'pc20.ov.p2'            : 'The opening pages present **"Honours"** and **"Culture"** — two brand pages showing the mall\'s awards and philosophy. Each month a **floor-themed illustration**: Pingping tours the mall with family and friends — from the 1st-floor watches and cosmetics to the 7th-floor down jackets, from kids\' sales to appliance cleaning — drawing the mall\'s tenant map across the whole year.',
    'pc20.ov.point1'        : 'The apple mascot runs through the year',
    'pc20.ov.point2'        : 'Two opening pages: honours & culture',
    'pc20.ov.point3'        : 'Each month a mall floor or business',
    'pc20.ov.point4'        : 'October: mall\'s 20th-anniversary event',
    'pc20.ft1.no'           : '01 — Year-of-the-Rat cover',
    'pc20.ft1.t'            : 'Mascot: apple',
    'pc20.ft1.p'            : 'Pingping is a mascot derived from an apple — pink rounded body, yellow stalk antennae and a green-leaf tail, instantly recognizable. On the 2020 Rat-year cover it shares the frame with mice, festive and lively.',
    'pc20.ft2.no'           : '02 — Two brand opening pages',
    'pc20.ft2.t'            : 'Honours + Culture',
    'pc20.ft2.p'            : 'The calendar opens with two brand pages: "Honours" displays the mall\'s past awards on a timeline, and "Culture" conveys its management philosophy — giving the calendar the added role of a brand handbook.',
    'pc20.ft3.no'           : '03 — Floor-themed illustration',
    'pc20.ft3.t'            : '12 months across the whole mall',
    'pc20.ft3.p'            : 'Each month\'s illustration matches a floor or business: watches and cosmetics on 1F, shoes and bags on 2F, menswear on 3F, kids\' and women\'s wear on 4F, lingerie on 5F, kids\' sales on 6F, down jackets on 7F, plus sports, appliances, jewellery and the 20th-anniversary celebration.',
    'pc20.ft4.no'           : '04 — Functional calendar page',
    'pc20.ft4.t'            : 'Solar terms + brand info',
    'pc20.ft4.p'            : 'The calendar page marks solar and lunar dates, solar terms and traditional festivals, and prints the brand line "Pingyuan — the mall of the people" at the foot, carrying the brand\'s warmth with every turn.',
    'pc20.mk1.cap'          : 'Spread · illustration and calendar page',
    'pc20.mk2.cap'          : 'Standing on a desk · Cover key visual',
