    'pc21.meta.title'       : 'Pingyuan Mall · 2021 Annual Calendar — JUN',
    'pc21.meta.desc'        : 'The 2021 annual calendar for Pingyuan Mall: the apple mascot "Pingping", a newspaper opening page and a postcard as two special pages, 12 floor-themed illustrations and 12 functional calendar pages — follow Pingping through every floor. Graphic design by JUN (Zhou Jun).',
    'pc21.nav.overview'     : 'Overview',
    'pc21.nav.features'     : 'Highlights',
