    'pc21.hero.title'       : 'Pingyuan Mall',
    'pc21.hero.sub'         : '2021 Annual Calendar · Year of the Ox',
    'pc21.hero.desc'        : 'An annual calendar led by the apple mascot Pingping: a newspaper opening and a postcard as two special pages, 12 floor-themed illustrations and 12 functional calendar pages — follow Pingping through every floor, both a date tool and a year-long brand canvas.',
    'pc21.hero.figcap'      : 'Cover mockup · Desktop',
