    'pc21.ov.type.k'        : 'Type',
    'pc21.ov.type.v'        : 'Annual calendar · Graphic design',
    'pc21.ov.year.k'        : 'Year',
    'pc21.ov.year.v'        : '2021 · Year of the Ox',
    'pc21.ov.pages.k'       : 'Pages',
