    'pc21.ov.mascot.k'      : 'Mascot',
    'pc21.ov.mascot.v'      : 'Pingping (apple-derived)',
    'pc21.ov.p1'            : 'This is the 2021 annual calendar made for **Pingyuan Mall**. The cover opens in festive Year-of-the-Ox mood — a golden ox shares the frame with the Pingping apple family, while a 囍-character building, fireworks, lanterns and bronze coins set the New Year tone.',
    'pc21.ov.p2'            : 'The opening pages innovate with **"Pingyuan Mall News"** — a newspaper-style page — and **"Pingyuan Post"** — a postcard: the first delivers the brand philosophy as a headline, the second adds stamps and postmarks for collecting. Each month a **floor-themed illustration**: Pingping tours the mall with family and friends — from Chow Tai Fook jewellery to 2F shoes and bags, from 3F sports to the 6F kids\' zone, from the 64th store anniversary to the new building\'s 21st — drawing the mall\'s tenant map and brand story across the whole year.',
    'pc21.ov.point1'        : 'The apple mascot runs through the year',
    'pc21.ov.point2'        : 'Newspaper + postcard special pages',
    'pc21.ov.point3'        : 'Each month a mall floor or business',
    'pc21.ov.point4'        : 'July: 64th store anniversary · Oct: 21st of new building',
    'pc21.ft1.no'           : '01 — Year-of-the-Ox cover',
    'pc21.ft1.t'            : 'Mascot: apple',
    'pc21.ft1.p'            : 'Pingping is a mascot derived from an apple — pink rounded body, yellow stalk antennae and a green-leaf tail, instantly recognizable. On the 2021 Ox-year cover the Pingping family shares the frame with a golden ox, festive and lively.',
    'pc21.ft2.no'           : '02 — Two special opening pages',
    'pc21.ft2.t'            : 'Mall News + Postcard',
    'pc21.ft2.p'            : 'The calendar opens with two creative pages: "Pingyuan Mall News" delivers the brand philosophy "The mall of the people" as a newspaper headline; the "Pingyuan Post" postcard page carries stamps and postmarks, adding collecting and interaction fun.',
    'pc21.ft3.no'           : '03 — Floor-themed illustration',
    'pc21.ft3.t'            : '12 months across the whole mall',
    'pc21.ft3.p'            : 'Each month\'s illustration matches a floor or business: Chow Tai Fook jewellery, shoes and bags on 2F, sports on 3F, premium women\'s wear on 4F, kids\' zone on 6F, down jackets on 7F, lingerie on 5F, plus the 64th store anniversary, caring for staff and the new building\'s 21st anniversary.',
    'pc21.ft4.no'           : '04 — Functional calendar page',
    'pc21.ft4.t'            : 'Illustration + calendar + terms',
    'pc21.ft4.p'            : 'In 2021 the calendar page takes a new layout — mascot illustration on the left, calendar grid on the right — marking solar and lunar dates, solar terms and traditional festivals, and printing the brand line "Pingyuan — the mall of the people" at the foot, carrying the brand\'s warmth with every turn.',
    'pc21.mk1.cap'          : 'Spread · illustration and calendar page',
    'pc21.mk2.cap'          : 'Standing on a desk · Cover key visual',
