    'pc22.ov.mascot.k'      : 'Mascot',
    'pc22.ov.mascot.v'      : 'Pingping (apple-derived)',
    'pc22.ov.p1'            : 'This is the 2022 annual calendar made for **Pingyuan Mall**. The cover opens in festive Year-of-the-Tiger mood — a golden tiger (with the 王 mark on its forehead) shares the frame with the Pingping apple family in period costume: a pipa-playing Chang\'e and a lion dancer in a tiger hat — against an orange-red radial backdrop of auspicious clouds and mountains.',
    'pc22.ov.p2'            : 'The opening pages innovate with the double **"Pingyuan Vouchers"** spread: thirty coupons cover brands from 1F to 9F, practical and collectible. Each month a **floor-themed illustration**: Pingping tours the mall with family and friends — from the jewellery-city proposal to the SHOES store, from the 3F sports hall to 4F womenswear, from the 65th-anniversary celebration to the new building\'s 22nd — drawing the mall\'s tenant map and brand story across the whole year.',
    'pc22.ov.point1'        : 'The apple mascot runs through the year',
    'pc22.ov.point2'        : 'Double voucher spread · 30 coupons',
    'pc22.ov.point3'        : 'Each month a mall floor or business',
    'pc22.ov.point4'        : 'July: 65th anniversary · October: new building\'s 22nd',
    'pc22.ft1.no'           : '01 — Year-of-the-Tiger cover',
    'pc22.ft1.t'            : 'Golden tiger × Pingping family in period costume',
    'pc22.ft1.p'            : 'Pingping is a mascot derived from an apple — pink rounded body, yellow stalk antennae and a green-leaf tail. On the 2022 Tiger-year cover the Pingping family dresses in period costume — a pipa-playing Chang\'e, a tiger-hat lion dancer — sharing the frame with the golden tiger against a powerful orange-red radial backdrop.',
    'pc22.ft2.no'           : '02 — Double voucher spread',
    'pc22.ft2.t'            : '30 coupons from 1F to 9F',
    'pc22.ft2.p'            : 'The calendar opens with two voucher pages — thirty brand coupons from 1F gold & jewellery and 3F sportswear to 9F dining and entertainment. Every floor has its own perk: flipping the calendar doubles as a shopping guide to the mall.',
    'pc22.ft3.no'           : '03 — Floor-themed illustration',
    'pc22.ft3.t'            : '12 months across the whole mall',
    'pc22.ft3.p'            : 'Each month\'s illustration matches a floor or business: the jewellery-city proposal, the SHOES store, the 3F sports hall, 4F womenswear, Children\'s Day, 7F off-season down jackets, Bafang appliances, 5F popular womenswear — plus the 65th anniversary and the new building\'s 22nd.',
    'pc22.ft4.no'           : '04 — Functional calendar page',
    'pc22.ft4.t'            : 'Calendar left, illustration right',
    'pc22.ft4.p'            : 'The 2022 calendar page pairs a left-hand date grid with a right-hand mascot illustration, marking solar and lunar dates, solar terms and traditional festivals; the illustration carries the month\'s theme and the foot prints brand lines like "Pingyuan Mall wishes the whole city a Happy New Year" — brand warmth with every turn.',
    'pc22.mk1.cap'          : 'Spread · illustration and calendar page',
