    'pc23.meta.title'       : 'Pingyuan Mall · 2023 Annual Calendar — JUN',
    'pc23.meta.desc'        : 'The 2023 annual calendar for Pingyuan Mall: the apple mascot "Pingping", a double bookmark spread, 12 floor-themed illustrations and 12 functional calendar pages — follow Pingping through every floor. Graphic design by JUN (Zhou Jun).',
