    'pc23.hero.sub'         : '2023 Annual Calendar · Year of the Rabbit',
    'pc23.hero.desc'        : 'An annual calendar led by the apple mascot Pingping: a Rabbit-year cover with a white rabbit riding a deer alongside a flying-apsara Pingping, a double spread of cut-out bookmarks, and 12 floor-themed illustrations — follow Pingping through every floor.',
    'pc23.hero.figcap'      : 'Cover mockup · Desktop',
