    'pc23.ov.mascot.v'      : 'Pingping (apple-derived)',
    'pc23.ov.p1'            : 'This is the 2023 annual calendar made for **Pingyuan Mall**. The cover opens in festive Year-of-the-Rabbit mood — a white rabbit in a flower crown rides a deer while the apple mascot Pingping turns flying apsara, playing flute and pipa and dancing — surrounded by sky lanterns, koi and auspicious clouds on a tender pink backdrop.',
    'pc23.ov.p2'            : 'The opening pages innovate with the double **"Pingping Bookmarks"** spread: eight cut-along-the-line bookmarks — Peace, Great Luck, Wishes Granted and the Rabbit New Year series — with traditional eave lanterns and lion-hat Pingping, "reading with you every day". Each month a **floor-themed illustration**: Pingping tours the mall — from the seven-brand gold & jewellery plaza to the 2F shoe store\'s dragon dance, from the 3F menswear café to 4F quality womenswear, from the 66th-anniversary construction celebration to the new building\'s 23rd — drawing the mall\'s tenant map and brand story across the whole year.',
    'pc23.ov.point1'        : 'The apple mascot runs through the year',
    'pc23.ov.point2'        : 'Double bookmark spread · 8 cut-outs',
    'pc23.ov.point3'        : 'Each month a mall floor or business',
    'pc23.ov.point4'        : 'July: 66th anniversary · October: new building\'s 23rd',
    'pc23.ft1.no'           : '01 — Year-of-the-Rabbit cover',
    'pc23.ft1.t'            : 'Rabbit riding a deer × flying-apsara Pingping',
    'pc23.ft1.p'            : 'Pingping is a mascot derived from an apple — pink rounded body, yellow stalk antennae and a green-leaf tail. On the 2023 Rabbit-year cover Pingping becomes a flying apsara playing flute and pipa, sharing the frame with a flower-crowned white rabbit riding a deer, amid sky lanterns, koi and clouds on a tender pink backdrop.',
    'pc23.ft2.no'           : '02 — Double bookmark spread',
    'pc23.ft2.t'            : '8 cut-out Pingping bookmarks',
    'pc23.ft2.p'            : 'The calendar opens with two bookmark pages — eight bookmarks to cut along the dotted lines: Peace, Great Luck, Wishes Granted and the Rabbit New Year series, with traditional eave lanterns and lion-hat Pingping, "reading with you every day — be my friend". Practical and collectible at once.',
    'pc23.ft3.no'           : '03 — Floor-themed illustration',
    'pc23.ft3.t'            : '12 months across the whole mall',
    'pc23.ft3.p'            : 'Each month\'s illustration matches a floor or business: the seven-brand gold & jewellery plaza, 2F shoes with a dragon dance, the 3F menswear café, 4F quality womenswear, the Children\'s Day carousel, 7F down jackets, Bafang appliances, 5F womenswear — plus the 66th anniversary and the new building\'s 23rd.',
    'pc23.ft4.no'           : '04 — Functional calendar page',
    'pc23.ft4.t'            : 'Calendar left, illustration right',
    'pc23.ft4.p'            : 'The 2023 calendar page pairs a left-hand date grid with a right-hand mascot illustration, marking solar and lunar dates, solar terms and traditional festivals; the illustration carries the month\'s theme and the foot prints brand lines like "Pingyuan Mall wishes the whole city a happy Rabbit New Year" — brand warmth with every turn.',
